const html: Record<string, string> = {"top":"<section class=\"gx gx-marquee\" aria-label=\"Built for\"><p class=\"gx-eyebrow\">Built for the people who keep funders informed</p><div class=\"gx-marquee-mask\"><ul class=\"gx-track\"><li>Grants managers</li><li>Finance directors</li><li>Programme leads</li><li>Executive directors</li><li>NGOs</li><li>Charities</li><li>Universities</li><li>Research offices</li><li>Community foundations</li><li>Social enterprises</li><li>Health nonprofits</li><li>Arts organisations</li><li aria-hidden=\"true\">Grants managers</li><li aria-hidden=\"true\">Finance directors</li><li aria-hidden=\"true\">Programme leads</li><li aria-hidden=\"true\">Executive directors</li><li aria-hidden=\"true\">NGOs</li><li aria-hidden=\"true\">Charities</li><li aria-hidden=\"true\">Universities</li><li aria-hidden=\"true\">Research offices</li><li aria-hidden=\"true\">Community foundations</li><li aria-hidden=\"true\">Social enterprises</li><li aria-hidden=\"true\">Health nonprofits</li><li aria-hidden=\"true\">Arts organisations</li></ul></div></section>\n<section id=\"problem\" class=\"gx gx-section\"><div class=\"gx-wrap\"><div><p class=\"gx-eyebrow\">The problem</p><h2 class=\"gx-h2\">Every grant comes with its own rules — and the evidence is scattered everywhere.</h2><p class=\"gx-intro\">Budgets in spreadsheets, receipts in inboxes, outcome evidence in shared drives, deadlines in someone’s calendar. Each funder wants a different report, and assembling it takes weeks.</p></div><div class=\"gx-grid gx-g3\"><figure class=\"gx-card gx-fig gx-reveal gx-lift gx-spot gx-d0\"><div class=\"gx-stat-v\"><small>$</small><b class=\"gx-b\" data-count=\"592.5\" data-dec=\"1\">592.5</b><span>B</span></div><figcaption><p>given to US charities in 2024 — every grant dollar comes with reporting obligations.</p><a class=\"gx-src\" href=\"https://givingusa.org/giving-usa-2025-u-s-charitable-giving-grew-to-592-50-billion-in-2024-lifted-by-stock-market-gains/\" target=\"_blank\" rel=\"noopener noreferrer\">Source: Giving USA 2025 ↗</a></figcaption></figure><figure class=\"gx-card gx-fig gx-reveal gx-lift gx-spot gx-d2\"><div class=\"gx-stat-v\"><small>$</small><b class=\"gx-b\" data-count=\"109.8\" data-dec=\"1\">109.8</b><span>B</span></div><figcaption><p>came from foundations — the funders most likely to require milestones, budgets and outcome evidence.</p><a class=\"gx-src\" href=\"https://givingusa.org/giving-usa-2025-u-s-charitable-giving-grew-to-592-50-billion-in-2024-lifted-by-stock-market-gains/\" target=\"_blank\" rel=\"noopener noreferrer\">Source: Giving USA 2025 ↗</a></figcaption></figure><figure class=\"gx-card gx-fig gx-reveal gx-lift gx-spot gx-d4\"><div class=\"gx-stat-v\"><b class=\"gx-b\" data-count=\"19\" data-dec=\"0\">19</b><span>%</span></div><figcaption><p>of all US charitable giving in 2024 came from foundation grants.</p><a class=\"gx-src\" href=\"https://foundationsource.com/blog/from-foundations-to-dafs-key-takeaways-from-giving-usas-2025-report-on-philanthropy/\" target=\"_blank\" rel=\"noopener noreferrer\">Source: Giving USA 2025, via Foundation Source ↗</a></figcaption></figure></div><p class=\"gx-small\">Published figures from Giving USA, linked above. They describe the scale of grant funding, not GrantLoom results.</p></div></section>\n<section id=\"solution\" class=\"gx gx-section gx-tint\"><div class=\"gx-wrap\"><div><p class=\"gx-eyebrow\">What we solve</p><h2 class=\"gx-h2\">From weeks of report assembly to funder-ready drafts with sources attached.</h2></div><div class=\"gx-grid gx-g2\"><div class=\"gx-card gx-reveal\"><p class=\"gx-eyebrow gx-eyebrow-muted\">Today</p><ul class=\"gx-list\"><li><span class=\"gx-ic no\" aria-label=\"No\">✕</span><span class=\"gx-muted\">Each funder’s requirements live in a different PDF.</span></li><li><span class=\"gx-ic no\" aria-label=\"No\">✕</span><span class=\"gx-muted\">Receipts and invoices are matched to budget lines by hand.</span></li><li><span class=\"gx-ic no\" aria-label=\"No\">✕</span><span class=\"gx-muted\">Outcome evidence is scattered across drives and inboxes.</span></li><li><span class=\"gx-ic no\" aria-label=\"No\">✕</span><span class=\"gx-muted\">Deadlines are tracked in personal calendars.</span></li><li><span class=\"gx-ic no\" aria-label=\"No\">✕</span><span class=\"gx-muted\">Reports are rebuilt from scratch every cycle.</span></li></ul></div><div class=\"gx-card gx-with gx-reveal gx-spot gx-d2\"><p class=\"gx-eyebrow\">With GrantLoom</p><ul class=\"gx-list\"><li><span class=\"gx-ic ok\" aria-label=\"Yes\">✓</span><span>Funder requirements extracted into a checklist per grant.</span></li><li><span class=\"gx-ic ok\" aria-label=\"Yes\">✓</span><span>Receipts analysed and mapped to budget lines for review.</span></li><li><span class=\"gx-ic ok\" aria-label=\"Yes\">✓</span><span>Outcome evidence linked to milestones.</span></li><li><span class=\"gx-ic ok\" aria-label=\"Yes\">✓</span><span>Deadlines and reminders across every grant.</span></li><li><span class=\"gx-ic ok\" aria-label=\"Yes\">✓</span><span>Report drafts that cite the source behind every figure.</span></li></ul></div></div></div></section>","mid":"<section id=\"compare\" class=\"gx gx-section\"><div class=\"gx-wrap\"><div><p class=\"gx-eyebrow\">Why GrantLoom</p><h2 class=\"gx-h2\">How it compares with the way grants are managed today</h2><p class=\"gx-intro\">GrantLoom works alongside your accounting system — it keeps every grant’s budget, evidence and deadlines woven together.</p></div><div class=\"gx-table-wrap gx-reveal\"><table class=\"gx-table\"><thead><tr><th><span class=\"gx-sr\">Capability</span></th><th>Spreadsheets &amp; drives</th><th>Accounting software</th><th>Grant databases</th><th class=\"gx-us\">GrantLoom</th></tr></thead><tbody><tr><th scope=\"row\">Funder requirements as a checklist</th><td><span class=\"gx-cell\"><span class=\"gx-ic no\" aria-label=\"No\">✕</span> PDFs</span></td><td><span class=\"gx-cell\"><span class=\"gx-ic no\" aria-label=\"No\">✕</span> —</span></td><td><span class=\"gx-cell\"><span class=\"gx-ic part\" aria-label=\"Partly\">–</span> Basic fields</span></td><td class=\"gx-us\"><span class=\"gx-cell\"><span class=\"gx-ic ok\" aria-label=\"Yes\">✓</span> Extracted, reviewed</span></td></tr><tr><th scope=\"row\">Expenditures mapped to budget lines</th><td><span class=\"gx-cell\"><span class=\"gx-ic part\" aria-label=\"Partly\">–</span> By hand</span></td><td><span class=\"gx-cell\"><span class=\"gx-ic part\" aria-label=\"Partly\">–</span> Cost codes</span></td><td><span class=\"gx-cell\"><span class=\"gx-ic no\" aria-label=\"No\">✕</span> —</span></td><td class=\"gx-us\"><span class=\"gx-cell\"><span class=\"gx-ic ok\" aria-label=\"Yes\">✓</span> Suggested, approved</span></td></tr><tr><th scope=\"row\">Outcome evidence linked to milestones</th><td><span class=\"gx-cell\"><span class=\"gx-ic no\" aria-label=\"No\">✕</span> Scattered</span></td><td><span class=\"gx-cell\"><span class=\"gx-ic no\" aria-label=\"No\">✕</span> —</span></td><td><span class=\"gx-cell\"><span class=\"gx-ic part\" aria-label=\"Partly\">–</span> Attachments</span></td><td class=\"gx-us\"><span class=\"gx-cell\"><span class=\"gx-ic ok\" aria-label=\"Yes\">✓</span> Per milestone</span></td></tr><tr><th scope=\"row\">Deadlines across every grant</th><td><span class=\"gx-cell\"><span class=\"gx-ic part\" aria-label=\"Partly\">–</span> Calendars</span></td><td><span class=\"gx-cell\"><span class=\"gx-ic no\" aria-label=\"No\">✕</span> —</span></td><td><span class=\"gx-cell\"><span class=\"gx-ic ok\" aria-label=\"Yes\">✓</span> Due dates</span></td><td class=\"gx-us\"><span class=\"gx-cell\"><span class=\"gx-ic ok\" aria-label=\"Yes\">✓</span> With reminders</span></td></tr><tr><th scope=\"row\">Report drafts with sources</th><td><span class=\"gx-cell\"><span class=\"gx-ic no\" aria-label=\"No\">✕</span> Rebuilt each cycle</span></td><td><span class=\"gx-cell\"><span class=\"gx-ic no\" aria-label=\"No\">✕</span> —</span></td><td><span class=\"gx-cell\"><span class=\"gx-ic no\" aria-label=\"No\">✕</span> —</span></td><td class=\"gx-us\"><span class=\"gx-cell\"><span class=\"gx-ic ok\" aria-label=\"Yes\">✓</span> Every figure cited</span></td></tr><tr><th scope=\"row\">Submits reports to funders on its own</th><td><span class=\"gx-cell\"><span class=\"gx-ic no\" aria-label=\"No\">✕</span> —</span></td><td><span class=\"gx-cell\"><span class=\"gx-ic no\" aria-label=\"No\">✕</span> —</span></td><td><span class=\"gx-cell\"><span class=\"gx-ic no\" aria-label=\"No\">✕</span> —</span></td><td class=\"gx-us\"><span class=\"gx-cell\"><span class=\"gx-ic no\" aria-label=\"No\">✕</span> By design — people approve</span></td></tr></tbody></table></div></div></section>\n<section id=\"ai\" class=\"gx gx-section gx-tint\"><div class=\"gx-wrap gx-split gx-even\"><div><div><p class=\"gx-eyebrow\">AI, used carefully</p><h2 class=\"gx-h2\">Drafts with visible sources — approved by your team.</h2><p class=\"gx-intro\">GrantLoom’s assistant reads funder requirements, receipts and evidence to draft reports. Every statement cites its source, and nothing is submitted without a person.</p></div><ul class=\"gx-list\"><li class=\"gx-card gx-li-card gx-reveal gx-lift gx-d0\"><span class=\"gx-ic ok\" aria-label=\"Yes\">✓</span><span>Extract funder requirements into a checklist</span></li><li class=\"gx-card gx-li-card gx-reveal gx-lift gx-d1\"><span class=\"gx-ic ok\" aria-label=\"Yes\">✓</span><span>Suggest which budget line a receipt belongs to</span></li><li class=\"gx-card gx-li-card gx-reveal gx-lift gx-d2\"><span class=\"gx-ic ok\" aria-label=\"Yes\">✓</span><span>Draft a funder report with cited sources</span></li><li class=\"gx-card gx-li-card gx-reveal gx-lift gx-d3\"><span class=\"gx-ic ok\" aria-label=\"Yes\">✓</span><span>Answer “what’s due this month?” across grants</span></li><li class=\"gx-card gx-li-card gx-reveal gx-lift gx-d4\"><span class=\"gx-ic no\" aria-label=\"No\">✕</span><span>Submit a report or claim to a funder</span></li><li class=\"gx-card gx-li-card gx-reveal gx-lift gx-d5\"><span class=\"gx-ic no\" aria-label=\"No\">✕</span><span>Invent outcomes or figures not in your records</span></li></ul></div><div class=\"gx-card gx-chat gx-reveal gx-d2\"><div class=\"gx-chat-head\">Grants assistant <span class=\"gx-badge\">Sample data</span></div><p class=\"gx-bubble-q\">What’s missing for the Q3 report to the Rivers Fund?</p><div class=\"gx-bubble-a\">Two items: the attendance evidence for Milestone 2 and receipts for $1,240 of travel. The narrative draft is ready and cites 14 records.<em>From the grant agreement, budget and evidence library</em></div><p class=\"gx-bubble-q\">Just say we hit the 500-participant target.</p><div class=\"gx-bubble-a gx-muted\">I can only report what your records show — 412 participants so far. I can flag the gap for your programme lead.</div><a class=\"gx-btn gx-mt\" href=\"#demo\">Try it in the live demo →</a></div></div></section>","end":"<section id=\"team\" class=\"gx gx-section gx-tint\"><div class=\"gx-wrap\"><div><p class=\"gx-eyebrow\">Team</p><h2 class=\"gx-h2\">The people building GrantLoom</h2><p class=\"gx-intro\">Founded by Ngozi Okafor (Founder/CEO) and Ibrahim Musa (Co-founder/CTO), and built together with the teams who will use it.</p></div><div class=\"gx-mt44\"><div class=\"gx gx-grid gx-g2 gx-mt0\"><article class=\"gx-card gx-reveal gx-lift gx-spot gx-d0\"><div class=\"gx-person\"><div class=\"gx-avatar\" aria-hidden=\"true\"><b>NO</b></div><div class=\"gx-min0\"><p class=\"gx-role\">Founder/CEO</p><h3>Ngozi Okafor</h3><p>Ngozi founded GrantLoom so grant teams can report with confidence instead of rebuilding evidence every cycle — and leads product, organisations and every pilot.</p><ul class=\"gx-tags\" aria-label=\"Focus areas\"><li>Product</li><li>Grant teams</li><li>Pilots</li></ul></div></div></article><article class=\"gx-card gx-reveal gx-lift gx-spot gx-d2\"><div class=\"gx-person\"><div class=\"gx-avatar\" aria-hidden=\"true\"><b>IM</b></div><div class=\"gx-min0\"><p class=\"gx-role\">Co-founder/CTO</p><h3>Ibrahim Musa</h3><p>Ibrahim co-founded GrantLoom and leads its technology — from requirement extraction and receipt analysis to the cloud platform behind it.</p><ul class=\"gx-tags\" aria-label=\"Focus areas\"><li>Document AI</li><li>Compliance engine</li><li>Cloud platform</li></ul></div></div></article></div></div></div></section>\n<section id=\"roadmap\" class=\"gx gx-section\"><div class=\"gx-wrap\"><div><p class=\"gx-eyebrow\">Roadmap</p><h2 class=\"gx-h2\">Where GrantLoom is going</h2><p class=\"gx-intro\">Built with early-access customers. The order below is our plan and may change based on what pilots teach us.</p></div><ol class=\"gx-grid gx-g4 gx-ol\"><li class=\"gx-card gx-reveal gx-lift gx-now gx-d0\"><div class=\"gx-stage\"><span><i class=\"gx-live\" aria-hidden=\"true\"></i>Now</span></div><h3>Live demo &amp; early access</h3><ul class=\"gx-list gx-list-sm\"><li><span class=\"gx-ic ok\" aria-label=\"Yes\">✓</span><span class=\"gx-muted\">Workspace on fictional grants</span></li><li><span class=\"gx-ic ok\" aria-label=\"Yes\">✓</span><span class=\"gx-muted\">Evidence mapping demo</span></li><li><span class=\"gx-ic ok\" aria-label=\"Yes\">✓</span><span class=\"gx-muted\">Budget, compliance and audit views</span></li><li><span class=\"gx-ic ok\" aria-label=\"Yes\">✓</span><span class=\"gx-muted\">Demo requests open</span></li></ul></li><li class=\"gx-card gx-reveal gx-lift gx-d2\"><div class=\"gx-stage\"><span>Next</span></div><h3>Pilot with one organisation</h3><ul class=\"gx-list gx-list-sm\"><li><span class=\"gx-ic part\" aria-label=\"Partly\">–</span><span class=\"gx-muted\">Requirement extraction with Amazon Bedrock</span></li><li><span class=\"gx-ic part\" aria-label=\"Partly\">–</span><span class=\"gx-muted\">Receipt analysis</span></li><li><span class=\"gx-ic part\" aria-label=\"Partly\">–</span><span class=\"gx-muted\">Report drafts with sources</span></li></ul></li><li class=\"gx-card gx-reveal gx-lift gx-d3\"><div class=\"gx-stage\"><span>Then</span></div><h3>General availability</h3><ul class=\"gx-list gx-list-sm\"><li><span class=\"gx-ic part\" aria-label=\"Partly\">–</span><span class=\"gx-muted\">Accounting-system import</span></li><li><span class=\"gx-ic part\" aria-label=\"Partly\">–</span><span class=\"gx-muted\">SSO with roles enforced on the server</span></li><li><span class=\"gx-ic part\" aria-label=\"Partly\">–</span><span class=\"gx-muted\">Funder-specific templates</span></li></ul></li><li class=\"gx-card gx-reveal gx-lift gx-d5\"><div class=\"gx-stage\"><span>Later</span></div><h3>Exploring with pilots</h3><ul class=\"gx-list gx-list-sm\"><li><span class=\"gx-ic part\" aria-label=\"Partly\">–</span><span class=\"gx-muted\">Funder portals</span></li><li><span class=\"gx-ic part\" aria-label=\"Partly\">–</span><span class=\"gx-muted\">Multi-currency grants</span></li><li><span class=\"gx-ic part\" aria-label=\"Partly\">–</span><span class=\"gx-muted\">Board reporting packs</span></li></ul></li></ol></div></section>\n<section id=\"faq\" class=\"gx gx-section\"><div class=\"gx-wrap gx-split\"><div><div><p class=\"gx-eyebrow\">FAQ</p><h2 class=\"gx-h2\">Questions grant teams ask</h2></div><a class=\"gx-link\" href=\"mailto:hello@grantloom.site\">✉ Email the founders</a></div><div class=\"gx-faq gx-reveal\"><details><summary>Does GrantLoom submit reports to funders?</summary><p>No. It drafts reports and prepares evidence; a person reviews and submits. Every figure in a draft cites the record it came from.</p></details><details><summary>What problem does it actually solve?</summary><p>Each grant has its own requirements, budget and evidence spread across drives and inboxes. GrantLoom keeps them together per grant and drafts funder reports with sources attached.</p></details><details><summary>Does it replace our accounting system?</summary><p>No. It works alongside it; expenditures can be imported and mapped to grant budget lines.</p></details><details><summary>How is AI used?</summary><p>To extract requirements, analyse receipts and draft reports — always with visible source references, and always reviewed by your team.</p></details><details><summary>How much does it cost?</summary><p>See the pricing section. Prices are illustrative and exclude taxes.</p></details><details><summary>Is it available today?</summary><p>GrantLoom is in early access. The workspace runs on fictional grants; a pilot runs on yours. Request a demo and a founder will reply personally.</p></details></div></div></section>","privacy":"<section class=\"gx gx-section gx-legal\"><div class=\"gx-wrap\"><p class=\"gx-eyebrow\">Review draft · operator details to be confirmed</p><h1 class=\"gx-h2\">Privacy notice</h1><h2>What this website is</h2><p>This website describes GrantLoom and includes an interactive demo that runs on sample data. No customer systems are connected.</p><h2>Demo data</h2><p>Changes you make in the demo are kept in your browser (local storage) or in the demo server’s memory and contain only sample data. Clearing site data removes them.</p><h2>Early-access requests</h2><p>When the request form is connected to a customer-relationship service (proposed: HubSpot), submitting it sends the fields you enter, your consent choices and the page address to that service so GrantLoom can reply. Product updates are sent only if you opt in. Until then, requests are kept in your browser and you are offered a pre-filled email to hello@grantloom.site.</p><h2>Analytics and cookies</h2><p>This website includes no advertising trackers. A hosting provider may process routine request data to serve and protect the site.</p><h2>Your requests</h2><p>Contact hello@grantloom.site with questions about information you have sent to GrantLoom, or to ask for it to be corrected or deleted.</p><p class=\"gx-small gx-mt34\">Contact: <a href=\"mailto:hello@grantloom.site\">hello@grantloom.site</a></p></div></section>","terms":"<section class=\"gx gx-section gx-legal\"><div class=\"gx-wrap\"><p class=\"gx-eyebrow\">Review draft · operator details to be confirmed</p><h1 class=\"gx-h2\">Terms of use</h1><h2>Demonstration only</h2><p>The demo runs on sample data. It is not a production system and must not be used for real grant reporting.</p><h2>People decide</h2><p>GrantLoom organises information and flags items for review. Decisions stay with qualified people on your team.</p><h2>Pricing and availability</h2><p>Prices shown are illustrative and exclude taxes. Early-access requests do not create a subscription or any commitment.</p><h2>Use of the site</h2><p>Use the site and demo lawfully. Do not upload personal or confidential information to the demo.</p><h2>Changes</h2><p>These terms are a review draft. Operator details, governing law and service terms will be set out before launch.</p><p class=\"gx-small gx-mt34\">Contact: <a href=\"mailto:hello@grantloom.site\">hello@grantloom.site</a></p></div></section>"};

